+source_root = "$TEST_CX_SRC"
+output_dir = "dist/proj"
+[sections.main]
+include = ["src/**"]
+exclude = []
+`);
+    const config = await loadCxConfig(p, {}, {});
+    expect(config.sourceRoot).toBe(testDir);
+  });
