+project_name = "proj"
+source_root = "."
+output_dir = "dist/proj"
+[output.extensions]
+unknown = ".txt"
+[sections.main]
+include = ["src/**"]
+exclude = []
+`);
+    await expect(loadCxConfig(p, {}, {})).rejects.toThrow(CxError);
